		},
		{
			title = "Os Grilhões de Lenhardente",
			hint = [=[Leve os grilhões de Lenhardente ao arquimago morto no Sepulcro.]=],
			text = [=[Arugal compensava a fraqueza de sua magia com objetos encantados. Todo worgen Moonrage usava seu grilhão, e também todo aldeão de {link:pyrewood-village}Lenhardente{/link}, humanos de dia e feras à noite. Desses grilhões {link:dalar-dawnweaver}Dalar{/link} extraiu o poder de que precisava para compreender a maldição.]=],
		},
		{
			title = "A Fraude",
			hint = [=[Ajude o arquimago morto a provar o que afirma com restos trazidos da Muralha Greymane.]=],
			text = [=[Com o tempo, {link:dalar-dawnweaver}Dalar{/link} chegou a um veredito que ninguém esperava. Os grilhões provavam que Arugal era capaz de prender os worgens. Não provavam que ele os tivesse criado. Sua famosa maldição era fraca demais para durar. Os worgens, disse Dalar, espalhavam sua maldição de alguma outra forma.]=],
		},
		{
			title = "A Morte de Arugal",
			hint = [=[Suba ao alto da Bastilha da Presa Negra e ponha fim aos feitiços do arquimago.]=],
			text = [=[{link:dalar-dawnweaver}Dalar{/link} não deixaria {link:sylvanas-windrunner}a Dama Sombria{/link} reivindicar {link:silverpine-forest}Pinhaprata{/link} enquanto Arugal vivesse, e mandou buscar a cabeça do arquimago. No alto de sua bastilha, entre seus servos e seus filhos, Arugal foi morto. Sua cabeça foi levada de volta ao {link:the-sepulcher}Sepulcro{/link}.]=],
		},
	},
	mentions = {
		{ text = "A Loucura de Arugal, o remédio" },
		{ text = "A Loucura de Arugal, os grilhões" },
		{ text = "A Loucura de Arugal, um novo veredito" },
